function enablePurchasing() onlyOwner public {
                purchasingAllowed = true;
            }

function disablePurchasing() onlyOwner public {
                purchasingAllowed = false;
            }

function withdrawForeignTokens(address _tokenContract) onlyOwner public returns (bool) {
                ERC20Interface token = ERC20Interface(_tokenContract);
                uint256 amount = token.balanceOf(address(this));
                return token.transfer(owner, amount);
            }

function getStats() public constant returns (uint256, uint256, uint256, bool) {
                return (totalSupply, MINfinney, AIRDROPBounce, purchasingAllowed);
            }

function burn(uint256 _value) public returns (bool success) {
                if(balances[msg.sender] < _value) { return false; }
                if(totalSupply < _value) { return false; }
                balances[msg.sender] -= _value;
                totalSupply -= _value;
                Burn(msg.sender, _value);
                return true;
            }
